query:
mutation($pid0: ID!, $opt0: OptionUpdateInput!, $val0: [OptionValueUpdateInput!], $pid1: ID!, $opt1: OptionUpdateInput!, $val1: [OptionValueUpdateInput!], $pid2: ID!, $opt2: OptionUpdateInput!, $val2: [OptionValueUpdateInput!], $pid3: ID!, $opt3: OptionUpdateInput!, $val3: [OptionValueUpdateInput!], $pid4: ID!, $opt4: OptionUpdateInput!, $val4: [OptionValueUpdateInput!]) {
  o0: productOptionUpdate(productId: $pid0, option: $opt0, optionValuesToUpdate: $val0) { product { id } userErrors { field message code } }
  o1: productOptionUpdate(productId: $pid1, option: $opt1, optionValuesToUpdate: $val1) { product { id } userErrors { field message code } }
  o2: productOptionUpdate(productId: $pid2, option: $opt2, optionValuesToUpdate: $val2) { product { id } userErrors { field message code } }
  o3: productOptionUpdate(productId: $pid3, option: $opt3, optionValuesToUpdate: $val3) { product { id } userErrors { field message code } }
  o4: productOptionUpdate(productId: $pid4, option: $opt4, optionValuesToUpdate: $val4) { product { id } userErrors { field message code } }
}
